/* Shared-site adapter for independently built application navigation.
 * Only touches navigation links, never model state, inputs, or app controls.
 */
(function () {
  function sync() {
    document.querySelectorAll('a[href="/#tools"], a[href="https://suarezcfi.com/#tools"]').forEach(function (a) { a.setAttribute('href', '/tools/'); });
    document.querySelectorAll('nav a[href]').forEach(function (a) {
      if (/\/blog\/$/.test(a.getAttribute('href')) && a.textContent.trim() === 'Journal') a.textContent = 'Blog';
    });
    // app-tool-links: generated by scripts/sync-site-metadata.py
    var items = [{"path":"/tools/","label":"All pilot tools","summary":"Explore the full collection"},{"path":"/simply-endorsed-cfi/","label":"Simply Endorsed CFI","summary":"FAA endorsement lookup","icon":"/assets/identities/simply-endorsed-cfi/logo.png"},{"path":"/part-61-calculator/","label":"CertPath","summary":"FAA rating planner","icon":"/assets/identities/part-61-calculator/logo.png"},{"path":"/flight-risk-assessment/","label":"FlightRisk","summary":"PAVE risk assessment","icon":"/assets/identities/flight-risk-assessment/logo.png"},{"path":"/engine-explorer/","label":"Crank & Core","summary":"3D engines & flight instruments","icon":"/assets/identities/engine-explorer/logo.png"},{"path":"/foi-cards/","label":"FOI Cards","summary":"Fundamentals of Instructing flashcards","icon":"/assets/identities/foi-cards/logo.png"},{"path":"/pilotsolve/","label":"PilotSolve","summary":"Mobile flight calculator","icon":"/assets/identities/pilotsolve/logo.png"}];
    // /app-tool-links
    document.querySelectorAll('.site-navigation__drop-panel, .nav-drop-panel, .explorer-menu-panel').forEach(function (menu) {
      var grid = menu.querySelector('.av-app-launcher');
      if (!grid) {
        grid = document.createElement('ul'); grid.className = 'av-app-launcher';
        grid.setAttribute('aria-label', 'Pilot apps'); menu.appendChild(grid);
      }
      items.forEach(function (item) {
        var a = Array.from(menu.querySelectorAll('a')).find(function (a) {
          try { return new URL(a.getAttribute('href'), location.href).pathname === item.path; } catch (_) { return false; }
        });
        if (a && (!item.icon || a.dataset.appTile === 'true')) return;
        if (!a) { a = document.createElement('a'); a.href = item.path; }
        if (!item.icon) {
          a.textContent = item.label; menu.insertBefore(a, grid); return;
        }
        a.classList.add('av-app-tile'); a.dataset.appTile = 'true';
        a.replaceChildren();
        var well = document.createElement('span'); well.className = 'av-app-icon';
        var icon = document.createElement('img'); icon.src = item.icon; icon.alt = ''; icon.width = 48; icon.height = 48;
        well.appendChild(icon); a.appendChild(well);
        var title = document.createElement('strong'); title.textContent = item.label; a.appendChild(title);
        var row = document.createElement('li'); row.appendChild(a); grid.appendChild(row);
      });
    });
  }
  sync();
  var root=document.getElementById('root');
  if (root) {
    var observer;
    function attach() {
      var nav=root.querySelector('nav') || document.querySelector('.explorer-dock');
      if (!nav) return false;
      if (observer) observer.disconnect();
      sync();
      new MutationObserver(sync).observe(nav,{childList:true,subtree:true});
      return true;
    }
    if (!attach()) {observer=new MutationObserver(attach);observer.observe(root,{childList:true,subtree:true});}
  }
})();
